<template><section class="builder-panel controls-panel"><header class="builder-panel__heading"><strong>♧ &nbsp; Test & Controls</strong></header><button class="visually-hidden demo-chat-access" type="button" :disabled="!chatSelected||chatLocked" @click="$emit('demo-chat-move')">Demo Chat Move · browser only</button><div class="test-grid"><button v-for="item in tests" :key="item.type" @click="$emit('test',item)">{{ item.icon }} {{ item.label }}</button><button @click="$emit('undo')">↶ &nbsp; Undo</button><button @click="$emit('redo')">↷ &nbsp; Redo</button><button @click="$emit('reset-scene')">◌ &nbsp; Reset Scene</button><label><input :checked="paused" type="checkbox" @change="$emit('pause',$event.target.checked)">Ⅱ &nbsp; Pause Animations</label></div><div class="control-row"><label>▦ &nbsp; Grid <input :checked="grid" type="checkbox" @change="$emit('grid',$event.target.checked)"></label><label>♧ &nbsp; Snapping <input :checked="snapping" type="checkbox" @change="$emit('snapping',$event.target.checked)"></label><label>⌗ &nbsp; Safe Zone <input :checked="safeZone" type="checkbox" @change="$emit('safe-zone',$event.target.checked)"></label></div></section></template>
<script setup>defineProps({paused:Boolean,grid:Boolean,snapping:Boolean,safeZone:Boolean,chatSelected:Boolean,chatLocked:Boolean});defineEmits(['test','pause','grid','snapping','safe-zone','undo','redo','reset-scene','reset-all','demo-chat-move']);const tests=[['stream.follow','alerts','♥','Test Follow'],['achievement.unlocked','achievement','🏆','Test Achievement'],['tts.requested','tts','▥','Test TTS']].map(([type,targetWidgetType,icon,label])=>({id:`test-${type}`,type,targetWidgetType,platform:type.startsWith('stream')||type.startsWith('tts')?'twitch':'respawn',actor:'Demo Creator',summary:label,createdAtLabel:'just now',payload:{demo:true},icon,label}))</script>
